function paintPreview(result){const dest=$('#poster');if(dest.width!==result.canvas.width)dest.width=result.canvas.width;if(dest.height!==result.canvas.height)dest.height=result.canvas.height;const ctx=dest.getContext('2d');ctx.clearRect(0,0,dest.width,dest.height);ctx.drawImage(result.canvas,0,0);posterEditor?.render(result);}
async function renderScheduledPreview(token){if(!current())return;const c=clone(current());previewBusy=true;try{const result=await renderPoster(c,1400,{interactive:true});if(token!==previewToken)return;previewResult=result;previewConfigId=c.id;paintPreview(result);$('#dimensions').textContent=`${result.canvas.width} × ${result.canvas.height} px · ${c.layout==='long'?'紧凑详情图':'1:1 固定方图'}`;$('#overflow').classList.toggle('hidden',!result.overflow);$('#overflow').textContent=`方图内容超出 ${result.needed-result.height}px。请减少模块间距、调整字号，或切换紧凑详情图。正式导出已暂停。`;$('#download').disabled=result.overflow;}catch(e){if(token===previewToken){$('#overflow').textContent=e.message;$('#overflow').classList.remove('hidden');$('#download').disabled=true;}}finally{previewBusy=false;if(token!==previewToken&&previewFrame===null)previewFrame=requestAnimationFrame(()=>{previewFrame=null;renderScheduledPreview(previewToken);});}}
