function openBatch(){const configs=chosen();if(!configs.length)return toast('请先勾选配置');openDialog('批量修改配置',`<button id="batch-addons">批量修改加购描述</button><p class="hint">影响 ${configs.length} 套：${esc(configs.map(c=>c.name).join('、'))}。只修改当前店铺选中配置，不变更其他配件。</p><div class="inline-grid"><label class="field">配件槽位<select id="batch-slot">${slots.map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field">数量<input id="batch-qty" type="number" min="1" value="1"></label></div><div id="batch-product-search"></div><div id="batch-diff" class="hint"></div><div class="actions"><button id="batch-check">查看修改预览</button><button id="batch-apply" class="primary" disabled>应用修改</button></div>`);let patch=null;const batchPicker=mountProductSearch($('#batch-product-search'),{getRows:currentCatalog,idKey:'sourceId',label:'新配件（不选择则只改数量）',inputId:'batch-id',onChange:()=>{$('#batch-apply').disabled=true;patch=null;}});$('#batch-addons').onclick=()=>openBatchAddons(()=>available().filter(c=>configs.some(x=>x.id===c.id)));$$('#dialog-body input:not([data-product-query]),#dialog-body select').forEach(el=>el.oninput=()=>{$('#batch-apply').disabled=true;patch=null;});$('#batch-check').onclick=()=>{const slot=$('#batch-slot').value,id=batchPicker.row()?.goodsId||'',qty=Number($('#batch-qty').value);if(!Number.isInteger(qty)||qty<1)return toast('数量必须为正整数');if(batchPicker.query().trim()&&!batchPicker.row())return toast('请点击下方搜索结果选择新配件');const choices=batchPicker.row()?[batchPicker.row()]:[];const affected=configs.filter(c=>c.parts.some(p=>p.slot===slot));if(!affected.length)return toast('所选配置都没有这个槽位');patch={slot,qty,part:id?clone(choices[0]):null,affected};patch.changes=affected.map(c=>{const after=clone(c),i=after.parts.findIndex(p=>p.slot===slot);if(patch.part)replaceSourcePart(after,i,patch.part);after.parts[i].qty=qty;return {id:c.id,before:clone(c),after};});$('#batch-diff').textContent=patch.changes.map(d=>{const p=d.before.parts.find(p=>p.slot===slot),a=d.after.parts.find(p=>p.slot===slot);return`${d.before.name}：${p.name} ×${p.qty} → ${a.name} ×${qty}`+(JSON.stringify(d.before.addons)!==JSON.stringify(d.after.addons)?'\n关联加购：'+(d.before.addons.map(a=>a.text).join('；')||'无')+' → '+(d.after.addons.map(a=>a.text).join('；')||'无'):'');}).join('\n');$('#batch-apply').disabled=false;};$('#batch-apply').onclick=()=>{try{if(!patch)return;applyReplacement(patch,clone(state.configs));checkpoint();const ids=applyReplacement(patch,state.configs);changed('批量修改配件及关联加购',ids);renderAll();closeDialog();}catch(e){toast(e.message);$('#batch-apply').disabled=true;}};}
function removeConfigurations(ids){const targets=available().filter(c=>ids.includes(c.id));if(!targets.length)return;checkpoint();const oldIndex=available().findIndex(c=>c.id===active);deleteConfigs(state.configs,targets.map(c=>c.id));targets.forEach(c=>c.deletionSessionId=session.id);targets.forEach(c=>{selected.delete(c.id);pendingImages.delete(c.id);imageRecords.delete(c.id);});if(!current())active=available()[Math.min(Math.max(0,oldIndex),available().length-1)]?.id||null;changed(`删除 ${targets.length} 套配置`,[]);renderAll();toast(`已删除 ${targets.length} 套配置，可点击“撤销”或从“已删除配置”恢复`);}
