function openProduct(edit=false){
 const product=currentProduct(),shop=currentShop();
 openDialog(edit?'编辑商品链接':'新增配置链接',`<p class="hint">当前店铺：<strong>${esc(shop.name)}</strong>。一个商品链接可包含多套配置，可从 WPS 粘贴配件创建，也可先创建空白配置。</p><label class="field">链接名称<input id="product-name" value="${edit?esc(product.name):''}" placeholder="例如：X400 白色主机"></label><label class="field">链接分类<input id="product-category" list="link-categories" maxlength="40" value="${edit?esc(product.category):''}" placeholder="选择分类或输入自定义分类"><datalist id="link-categories">${linkCategories().map(cat=>`<option value="${esc(cat)}"></option>`).join('')}</datalist></label><label class="field">商品网址（可稍后填写）<input id="product-url" type="url" value="${edit?esc(product.url):''}" placeholder="https://…"></label><label class="field">SPU（可稍后填写）<input id="product-spu" value="${edit?esc(product.spu):''}" inputmode="numeric"></label>${edit?'':'<div id="wps-import-mount"></div>'}<div class="actions"><button id="product-apply" class="primary">${edit?'保存链接':'创建并编辑配置'}</button></div>`);
 const importer=edit?null:mountWpsImport($('#wps-import-mount'),{catalog:currentCatalog(),costSource:selectableComponents(state.costSource),configs:available()});
 $('#product-url').onchange=()=>{try{const id=new URL($('#product-url').value).searchParams.get('id');if(id&&/^\d+$/.test(id)&&!$('#product-spu').value)$('#product-spu').value=id;}catch{}};
 $('#product-apply').onclick=()=>{
  const category=$('#product-category').value.trim(),name=$('#product-name').value.trim(),url=$('#product-url').value.trim(),spu=$('#product-spu').value.trim();
  if(!name)return toast('请输入链接名称');if(url){try{if(!['http:','https:'].includes(new URL(url).protocol))throw Error();}catch{return toast('请输入完整的 http 或 https 商品网址');}}if(spu&&!/^\d+$/.test(spu))return toast('SPU 只能包含数字');
  let imported;try{imported=importer?.read();}catch(e){return toast(e.message);}if(!edit&&state.configs.length+(imported?.groups.length||1)>500)return toast('导入后超过 500 套配置，请减少导入数量');checkpoint();
  if(edit){product.configs.forEach(c=>Object.assign(c,{product:name,productCategory:category,productUrl:url,spu}));changed('编辑商品链接',product.configs.map(c=>c.id));}
  else{
   const target={id:crypto.randomUUID(),shopId:activeShopId,name,url,spu,category},reference=current()||state.configs.find(c=>!c.deletedAt)||state.configs[0];
   const added=(imported?.groups||[null]).map((group,index)=>{const c=applyShopIdentity(blankConfig(reference,target,group?.name||`配置${index+1}`),activeShopId,{resetAppearance:true});if(group){c.parts=group.parts;if(group.version)c.version=group.version;c.wpsImport={sourceText:group.sourceText,importedAt:imported.importedAt,lineStart:group.lineStart};c.installment=0;}else c.emptyLinkDraft=true;return c;});
   state.configs.push(...added);active=added[0].id;selected=new Set(added.map(c=>c.id));changed(imported?`从 WPS 导入 ${added.length} 套配置`:'新增配置链接',added.map(c=>c.id));
  }
  renderAll();closeDialog();
 };
}
