function openCopyToShop(){const source=current(),targets=shops.filter(shop=>shop.id!==activeShopId);openDialog('复制到其他店铺',`<p class="hint">复制当前配置的配件和数量，重新使用目标店输出名称与图片配色。SPU、SKU、售价、加购、福利和店铺服务文案将清空。</p><label class="field">目标店铺<select id="copy-shop-target">${targets.map(shop=>`<option value="${shop.id}">${esc(shop.name)}</option>`).join('')}</select></label><label class="field">目标商品链接名称<input id="copy-shop-product" value="${esc(source.product)}"></label><div class="actions"><button id="copy-shop-apply" class="primary">复制并切换到目标店铺</button></div>`);$('#copy-shop-apply').onclick=()=>{const targetShopId=$('#copy-shop-target').value,targetShop=shopById(targetShopId),productName=$('#copy-shop-product').value.trim();if(!productName)return toast('请输入目标商品链接名称');checkpoint();const targetProduct={id:crypto.randomUUID(),shopId:targetShopId,name:productName,category:source.productCategory||'',url:'',spu:''},copy=clone(source);Object.assign(copy,{id:crypto.randomUUID(),shopId:targetShopId,productId:targetProduct.id,product:productName,productUrl:'',spu:'',skuId:'',price:0,addons:[],benefits:[],updatedAt:null,taxUpdatedAt:null,erpImportedAt:null,shortName:'',shortNameAuto:true});for(const part of copy.parts){const row=state.sourceCatalog.find(item=>item.shopId===targetShopId&&item.goodsId===part.goodsId);if(row)Object.assign(part,{sourceId:row.sourceId,name:row.name,upgrade:row.upgrade,warranty:row.warranty,erp:row.erp,tax:row.tax});else delete part.sourceId;}for(const module of copy.modules||[])if(module.type==='service')module.text='';copy.footer='';applyShopIdentity(copy,targetShopId,{resetAppearance:true});state.configs.push(copy);activeShopId=targetShopId;localStorage.setItem('diy-active-shop',targetShopId);active=copy.id;selected=new Set([copy.id]);changed(`复制配置到${targetShop.name}`,[copy.id]);renderAll();closeDialog();toast(`已复制到${targetShop.name}，请补充商品身份、售价和本店文案`);};}
