 $$('[data-template-delete]').forEach(b=>b.onclick=()=>{const t=state.templates.find(t=>t.id===b.dataset.templateDelete);if(!t)return;checkpoint();t.deletedAt=new Date().toISOString();templateConfigs(t).forEach((c,i)=>picked.delete(t.id+':'+i));changed(`删除配置模板：${t.name}`,[]);draw();const notice=document.createElement('div');notice.className='template-notice';notice.setAttribute('role','status');notice.textContent=`已删除“${t.name}”。`;const undo=document.createElement('button');undo.textContent='撤销删除';undo.onclick=()=>restore(t.id);notice.append(undo);$('#templates-list').before(notice);});
 const restore=id=>{const t=state.templates.find(t=>t.id===id);if(!t)return;checkpoint();delete t.deletedAt;changed(`恢复配置模板：${t.name}`,[]);draw();toast('模板已恢复');};
